1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Rejects a create-owner request when the request's city already contains the maximum number of
11	 * owners ({@link CityAtCapacityException#CAPACITY}). Existing owners are counted with their city
12	 * compared case-insensitively and trimmed. Runs before {@link SaveOwner}, so the new owner is not
13	 * yet counted; a city holding 50 or more owners causes the 51st request to fail with 409.
14	 */
15	public class EnsureCityCapacity {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws CityAtCapacityException {
19	        String city = normalize(request.getCity());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (city.equals(normalize(existing.getCity()))) {
23	                count++;
24	            }
25	        }
26	        if (count >= CityAtCapacityException.CAPACITY) {
27	            throw new CityAtCapacityException(request.getCity(), count);
28	        }
29	    }
30	
31	    private static String normalize(String value) {
32	        return value == null ? "" : value.trim().toLowerCase();
33	    }
34	}
