3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
11	
12	public class BuildOwner {
13	
14	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
15	            throws FutureRegistrationDateException {
16	        Owner owner = ownerMapper.toOwner(request);
17	        // A newly created owner is not deleted.
18	        owner.setDeleted(false);
19	        LocalDate effective = owner.getRegistrationDate();
20	        if (effective == null) {
21	            effective = LocalDate.now();
22	        }
23	        // A supplied registration date cannot be in the future; reject a date later than the
24	        // server's current date with a 400 before it is rolled onto a business day.
25	        else if (effective.isAfter(LocalDate.now())) {
26	            throw new FutureRegistrationDateException(effective);
27	        }
28	        // The effective registration date must fall on a business day, whether supplied in the
29	        // request or defaulted to the server date; a weekend or public holiday rolls forward to the
30	        // next non-holiday business day.
31	        owner.setRegistrationDate(BusinessDays.rollForward(effective));
32	        built.set(owner);
33	    }
34	}
