146	        boolean dbl = true;
147	        for (int i = code.length() - 1; i >= 0; i--) {
148	            char c = code.charAt(i);
149	            if (c < '0' || c > '9') {
150	                continue;
151	            }
152	            int d = c - '0';
153	            if (dbl) {
154	                d *= 2;
155	                if (d > 9) {
156	                    d -= 9;
157	                }
158	            }
159	            sum += d;
160	            dbl = !dbl;
161	        }
162	        return (10 - (sum % 10)) % 10;
163	    }
164	
165	    /**
166	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of the fiscal
167	     * year the business-day-adjusted registrationDate falls in (fiscal year starting 1 July), e.g.
168	     * {@code FY27}. Null when the registration date is absent.
169	     */
170	    default String fiscalYear(Owner owner) {
171	        if (owner.getRegistrationDate() == null) {
172	            return null;
173	        }
174	        return String.format("FY%02d",
175	                org.springframework.samples.petclinic.rest.function.owner.OwnerMembership
176	                        .fiscalYearOf(owner.getRegistrationDate()) % 100);
177	    }
178	
179	    /**
180	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
181	     * digits of the fiscal year the registrationDate falls in (fiscal year starting 1 July), e.g.
182	     * {@code NSW-1A2B3C4D-M27}. Null when either the customer code or the registration date is absent.
183	     */
184	    default String membershipNumber(Owner owner) {
185	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
186	            return null;
187	        }
188	        return String.format("%s-M%02d", owner.getCustomerCode(),
189	                org.springframework.samples.petclinic.rest.function.owner.OwnerMembership
190	                        .fiscalYearOf(owner.getRegistrationDate()) % 100);
191	    }
192	
193	    Owner toOwner(OwnerDto ownerDto);
194	
195	    @Mapping(target = "id", ignore = true)
196	    @Mapping(target = "pets", ignore = true)
197	    Owner toOwner(OwnerFieldsDto ownerDto);
198	
199	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
200	
201	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
202	
203	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
204	        OwnerPageDto ownerPageDto = new OwnerPageDto();
205	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
206	        ownerPageDto.setPage(ownerPage.getNumber());
207	        ownerPageDto.setSize(ownerPage.getSize());
208	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
209	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
210	        return ownerPageDto;
211	    }
212	}
